#include "TorIntegrity.hpp"
#include "PrivatePaths.hpp"

#include <QCryptographicHash>
#include <QDir>
#include <QDirIterator>
#include <QFile>
#include <QFileInfo>
#include <QHash>
#include <QSet>
#include <QTcpSocket>

#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

namespace {

struct ManifestEntry { const char* path; const char* sha256; };

// Generated by cmake/GenTorManifest.cmake into the build tree.
// Defines: kTorManifest[] (terminated by {nullptr, nullptr}) and kTorBundleInfo.
#include "TorManifest.inc"

bool ignoredPath(const QString& rel)
{
    return rel.startsWith(QLatin1String("docs/")) || rel.startsWith(QLatin1String("debug/"));
}

QByteArray sha256Hex(const QString& path)
{
    QFile f(path);
    if (!f.open(QIODevice::ReadOnly))
        return {};
    QCryptographicHash h(QCryptographicHash::Sha256);
    if (!h.addData(&f))
        return {};
    return h.result().toHex();
}

QByteArray bakedHash(const char* rel)
{
    for (const ManifestEntry* e = kTorManifest; e->path; ++e)
        if (qstrcmp(e->path, rel) == 0)
            return QByteArray(e->sha256);
    return {};
}

QString readLinkStr(const QByteArray& path)
{
    char buf[4096];
    const ssize_t n = ::readlink(path.constData(), buf, sizeof(buf) - 1);
    if (n <= 0)
        return {};
    return QString::fromLocal8Bit(buf, int(n));
}

// Socket inodes listening on kSocksPort (IPv4 + IPv6).
QSet<QString> listeningInodes()
{
    QSet<QString> out;
    const QString portHex = QStringLiteral("%1").arg(TorIntegrity::kSocksPort, 4, 16, QLatin1Char('0')).toUpper();
    for (const char* table : {"/proc/net/tcp", "/proc/net/tcp6"}) {
        QFile f(QString::fromLatin1(table));
        if (!f.open(QIODevice::ReadOnly | QIODevice::Text))
            continue;
        f.readLine(); // header
        while (!f.atEnd()) {
            const QStringList cols = QString::fromLatin1(f.readLine()).simplified().split(QLatin1Char(' '));
            if (cols.size() < 10)
                continue;
            const QString local = cols.at(1);
            if (!local.endsWith(QLatin1Char(':') + portHex))
                continue;
            if (cols.at(3) != QLatin1String("0A")) // LISTEN
                continue;
            out.insert(cols.at(9));
        }
    }
    return out;
}

// pid owning socket:[inode], or -1 if not visible to us.
qint64 ownerOf(const QString& inode)
{
    const QByteArray want = "socket:[" + inode.toLatin1() + "]";
    DIR* proc = ::opendir("/proc");
    if (!proc)
        return -1;
    qint64 found = -1;
    while (dirent* d = ::readdir(proc)) {
        if (d->d_name[0] < '0' || d->d_name[0] > '9')
            continue;
        const QByteArray fdDir = QByteArray("/proc/") + d->d_name + "/fd";
        DIR* fds = ::opendir(fdDir.constData());
        if (!fds)
            continue;
        while (dirent* fd = ::readdir(fds)) {
            if (fd->d_name[0] == '.')
                continue;
            char buf[128];
            const QByteArray link = fdDir + "/" + fd->d_name;
            const ssize_t n = ::readlink(link.constData(), buf, sizeof(buf) - 1);
            if (n > 0 && QByteArray(buf, int(n)) == want) {
                found = QByteArray(d->d_name).toLongLong();
                break;
            }
        }
        ::closedir(fds);
        if (found > 0)
            break;
    }
    ::closedir(proc);
    return found;
}

bool portAnswers()
{
    QTcpSocket s;
    s.connectToHost(QStringLiteral("127.0.0.1"), TorIntegrity::kSocksPort);
    return s.waitForConnected(300);
}

void makePrivateDir(const QString& path)
{
    QDir().mkpath(path);
    ::chmod(QFile::encodeName(path).constData(), 0700);
}

} // namespace

namespace TorIntegrity {

QString executableDir()
{
    const QString exe = readLinkStr("/proc/self/exe");
    if (exe.isEmpty())
        return {};
    return QFileInfo(exe).canonicalPath();
}

QString resolveTorDir(QString* why)
{
    const QByteArray env = qgetenv("INCO_TOR_DIR");
    if (!env.isEmpty()) {
        const QString d = QString::fromLocal8Bit(env);
        if (QDir::isRelativePath(d)) {
            if (why) *why = QStringLiteral("INCO_TOR_DIR must be an absolute path (got \"%1\")").arg(d);
            return {};
        }
        const QFileInfo fi(d);
        if (!fi.isDir()) {
            if (why) *why = QStringLiteral("INCO_TOR_DIR does not exist: %1").arg(d);
            return {};
        }
        return fi.canonicalFilePath();
    }
    const QString exeDir = executableDir();
    if (exeDir.isEmpty()) {
        if (why) *why = QStringLiteral("cannot resolve /proc/self/exe");
        return {};
    }
    for (const QString& cand : {exeDir + QStringLiteral("/tor"), exeDir + QStringLiteral("/../tor")}) {
        if (QFileInfo(cand + QStringLiteral("/tor")).isFile())
            return QFileInfo(cand).canonicalFilePath();
    }
    if (why) *why = QStringLiteral("no tor/ bundle next to %1 (set INCO_TOR_DIR)").arg(exeDir);
    return {};
}

Result verifyBundle()
{
    Result r;
    if (!kTorManifest[0].path) {
        r.status = Status::NoManifest;
        r.problems << QStringLiteral("this build has no baked Tor hashes (tor/ was missing at build time)");
        return r;
    }
    QString why;
    r.torDir = resolveTorDir(&why);
    if (r.torDir.isEmpty()) {
        r.status = Status::NotFound;
        r.problems << why;
        return r;
    }
    r.torBin = r.torDir + QStringLiteral("/tor");

    QSet<QString> expected;
    for (const ManifestEntry* e = kTorManifest; e->path; ++e) {
        const QString rel = QString::fromUtf8(e->path);
        expected.insert(rel);
        const QString path = r.torDir + QLatin1Char('/') + rel;
        const QFileInfo fi(path);
        if (fi.isSymLink()) {
            r.problems << QStringLiteral("symlink not allowed: %1").arg(rel);
            continue;
        }
        if (!fi.isFile()) {
            r.problems << QStringLiteral("missing: %1").arg(rel);
            continue;
        }
        if (sha256Hex(path) != QByteArray(e->sha256))
            r.problems << QStringLiteral("changed: %1").arg(rel);
    }

    QDirIterator it(r.torDir,
                    QDir::Files | QDir::Hidden | QDir::System | QDir::NoDotAndDotDot,
                    QDirIterator::Subdirectories);
    const QDir base(r.torDir);
    while (it.hasNext()) {
        const QString rel = base.relativeFilePath(it.next());
        if (ignoredPath(rel) || expected.contains(rel))
            continue;
        r.problems << QStringLiteral("unexpected file: %1").arg(rel);
    }

    r.status = r.problems.isEmpty() ? Status::Ok : Status::Failed;
    return r;
}

bool runningBinaryMatches(qint64 pid)
{
    if (pid <= 0)
        return false;
    const QByteArray want = bakedHash("tor");
    if (want.isEmpty())
        return false;
    return sha256Hex(QStringLiteral("/proc/%1/exe").arg(pid)) == want;
}

PortState socksPortState(const Result& verified, QString* detail)
{
    const QSet<QString> inodes = listeningInodes();
    if (inodes.isEmpty()) {
        if (portAnswers()) {
            if (detail) *detail = QStringLiteral("127.0.0.1:%1 answers but its owner is not visible").arg(kSocksPort);
            return PortState::Foreign;
        }
        return PortState::Free;
    }
    for (const QString& inode : inodes) {
        const qint64 pid = ownerOf(inode);
        if (pid <= 0) {
            if (detail) *detail = QStringLiteral("127.0.0.1:%1 is held by a process Inco cannot inspect").arg(kSocksPort);
            return PortState::Foreign;
        }
        const QString exe = readLinkStr(QStringLiteral("/proc/%1/exe").arg(pid).toLocal8Bit());
        if (!verified.ok() || exe != verified.torBin || !runningBinaryMatches(pid)) {
            if (detail) *detail = QStringLiteral("127.0.0.1:%1 is held by %2 (pid %3), not the verified bundled Tor")
                                      .arg(kSocksPort).arg(exe.isEmpty() ? QStringLiteral("?") : exe).arg(pid);
            return PortState::Foreign;
        }
    }
    return PortState::OurTor;
}

QString dataDir()
{
    // Per-user tmpfs, or a random 0700 temp folder for this process when
    // XDG_RUNTIME_DIR is missing. Tor state never lands in the home folder.
    const QString base = PrivatePaths::runtimeDir();
    if (base.isEmpty())
        return {};
    const QString d = base + QStringLiteral("/tor-data");
    makePrivateDir(d);
    return d;
}

int manifestFileCount()
{
    int n = 0;
    for (const ManifestEntry* e = kTorManifest; e->path; ++e)
        ++n;
    return n;
}

QString bakedBundleInfo()
{
    return QString::fromUtf8(kTorBundleInfo).trimmed();
}

QString describe(const Result& r)
{
    QStringList lines;
    switch (r.status) {
    case Status::Ok:
        return QStringLiteral("Tor integrity check passed (%1 files, %2)").arg(manifestFileCount()).arg(r.torDir);
    case Status::NoManifest:
        lines << QStringLiteral("Tor integrity check unavailable.");
        break;
    case Status::NotFound:
        lines << QStringLiteral("Tor bundle not found.");
        break;
    case Status::Failed:
        lines << QStringLiteral("Tor integrity check failed for %1:").arg(r.torDir);
        break;
    }
    const int shown = qMin<int>(r.problems.size(), 8);
    for (int i = 0; i < shown; ++i)
        lines << QStringLiteral("  • ") + r.problems.at(i);
    if (r.problems.size() > shown)
        lines << QStringLiteral("  • … and %1 more").arg(r.problems.size() - shown);
    return lines.join(QLatin1Char('\n'));
}

} // namespace TorIntegrity
